import { RoomPlanCaptureService } from './apps/api/src/index.ts';
import { readFileSync, mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const dir=mkdtempSync(join(tmpdir(),'rv-'));
const svc=new RoomPlanCaptureService({storage_directory:dir,token_secret:'x',handoff_base_url:'x',handoff_ttl_ms:1000});
const req=JSON.parse(readFileSync('./fixtures/roomplan/bedroom-primary/capture-request.json','utf8'));
const cap=svc.postRoomPlanCapture(req);
const scene=svc.getScene(cap.scene_id)!;
const objects=Object.fromEntries(scene.snapshot.state.room.objects.map((o:any)=>[o.class,o]));
const floor=scene.snapshot.state.room.shell.surfaces.find((s:any)=>s.type==='floor');
const wall=scene.snapshot.state.room.shell.surfaces.find((s:any)=>s.type==='wall');
const namedWall=scene.snapshot.state.room.shell.named_wall_refs[0];
const door=scene.snapshot.state.room.shell.openings.find((o:any)=>o.type==='door');
function tryReq(name:string, req:any){
  try {
    const res=svc.createScenePreview(cap.scene_id, req);
    console.log(name,'OK',JSON.stringify(res.validation_summary.hard_violations));
  } catch (e:any) {
    console.log(name,'ERR',e.reason_code,e.message);
  }
}

